    let list = unsafe { &mut *lists.offset(index as isize) }; // SAFETY: caller guarantees `lists` points to a valid array of list entries; `index` is used identically to the original code.
    let oldchain = list[1];
    let lastcount = unsafe { (*oldchain).count }; // SAFETY: `list[1]` is assumed valid by the original function and dereferenced there as well.

    if index == 0 && lastcount >= numsymbols {
        return;
    }

    let newchain = unsafe {
        let p = (*pool).next;
        (*pool).next = p.offset(1);
        p
    }; // SAFETY: caller guarantees `pool->next` points into a valid node pool with available capacity, matching the original code's assumptions.

    list[0] = oldchain;
    list[1] = newchain;

