        return;
    }

    let prev = unsafe { &mut *lists.offset((index - 1) as isize) }; // SAFETY: `index > 0` here, and the caller/original code assumes the previous list entry exists and is valid.
    let sum = unsafe { (*prev[0]).weight.wrapping_add((*prev[1]).weight) }; // SAFETY: `prev[0]` and `prev[1]` are dereferenced in the original under the same conditions.

    if lastcount < numsymbols {
        let leaf = unsafe { &*leaves.offset(lastcount as isize) }; // SAFETY: guarded by `lastcount < numsymbols`, matching the original valid leaf access.
